def semver_compare(a, b):
    va = parse_version(a)
    vb = parse_version(b)

    # Compare major, minor, patch numerically
    if va['major'] != vb['major']:
        return -1 if va['major'] < vb['major'] else 1
    if va['minor'] != vb['minor']:
        return -1 if va['minor'] < vb['minor'] else 1
    if va['patch'] != vb['patch']:
        return -1 if va['patch'] < vb['patch'] else 1

    # Both have same numeric part, now handle prerelease
    a_pr = va['prerelease']
    b_pr = vb['prerelease']

    # Both without prerelease => equal
    if a_pr is None and b_pr is None:
        return 0
    # a has prerelease, b does not => a lower
    if a_pr is not None and b_pr is None:
        return -1
    # b has prerelease, a does not => a higher
    if a_pr is None and b_pr is not None:
        return 1

    # Both have prerelease, compare identifier by identifier
    max_len = max(len(a_pr), len(b_pr))
    for i in range(max_len):
        a_id = a_pr[i] if i < len(a_pr) else None
        b_id = b_pr[i] if i < len(b_pr) else None

        if a_id is not None and b_id is not None:
            a_digit = a_id.isdigit()
            b_digit = b_id.isdigit()
            if a_digit and b_digit:
                # numeric comparison
                if int(a_id) < int(b_id):
                    return -1
                if int(a_id) > int(b_id):
                    return 1
                # equal, continue
            elif not a_digit and not b_digit:
                # ASCII comparison
                if a_id < b_id:
                    return -1
                if a_id > b_id:
                    return 1
                # equal, continue
            else:
                # one digit, one not: digit is lower
                if a_digit:
                    return -1
                else:
                    return 1
        else:
            # One of them is None (i.e., we exhausted identifiers)
            if a_id is None and b_id is not None:
                # a shorter => lower
                return -1
            if b_id is None and a_id is not None:
                # a longer => higher
                return 1
            # both None should not happen; continue

    # All compared identifiers equal
    return 0

